CREATE DEFINER=`root`@`localhost` PROCEDURE `AddCar` (IN `c_brand` VARCHAR(20), IN `c_model` VARCHAR(32), IN `c_cc` VARCHAR(10), IN `c_year` INT, IN `c_license_plate` VARCHAR(10), IN `c_category` VARCHAR(16), IN `c_available` TINYINT, IN `c_price_per_day` INT, IN `c_mileage` INT, IN `c_isDiesel` TINYINT(10), IN `c_last_service_date` DATE, IN `c_seats` INT, IN `c_isManual` TINYINT, IN `c_car_picture` LONGBLOB, IN `c_description` VARCHAR(1000), IN `c_equipment` VARCHAR(1000), IN `c_doors` INT)   BEGIN
    -- Insert into car_pictures table
    INSERT INTO car_pictures (thumbnail)
    VALUES (c_car_picture); -- c_car_picture_blob is the binary data for the BLOB

    -- Get the last inserted ID for car_pictures
    SET @car_picture_id = LAST_INSERT_ID();

    -- Insert into cars table
    INSERT INTO cars (brand, model, cc, year, license_plate, category, available, price_per_day, mileage, isDiesel, last_service_date, car_picture_id, seats, doors, isManual)
    VALUES (c_brand, c_model, c_cc, c_year, c_license_plate, c_category, c_available, c_price_per_day, c_mileage, c_isDiesel, c_last_service_date, @car_picture_id, c_seats, c_doors, c_isManual);

    -- Get the last inserted ID for cars
    SET @car_id = LAST_INSERT_ID();

    -- Insert into car_data table
    INSERT INTO car_data (car_id, description, equipments)
    VALUES (@car_id, c_description, c_equipment);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `AddCar2` (IN `c_brand` VARCHAR(20), IN `c_model` VARCHAR(32), IN `c_cc` VARCHAR(10), IN `c_year` INT, IN `c_license_plate` VARCHAR(10), IN `c_category` VARCHAR(16), IN `c_available` TINYINT, IN `c_price_per_day` INT, IN `c_mileage` INT, IN `c_isDiesel` TINYINT, IN `c_last_service_date` DATE, IN `c_seats` INT, IN `c_doors` INT, IN `c_isManual` TINYINT, IN `c_car_picture_id` INT)   BEGIN
