CREATE DEFINER=`root`@`localhost` PROCEDURE `AddRental` (IN `c_car_id` INT, IN `c_customer_id` INT, IN `c_rental_date` DATE, IN `c_return_date` DATE, IN `c_total_price` INT, IN `c_deposit_amount` INT, IN `c_deposit_status` TINYINT)   BEGIN
