    VALUES (c_car_id, c_customer_id, c_rental_date, c_return_date, c_total_price, c_deposit_amount, c_deposit_status);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ApproveRentRequest` (IN `p_rent_approval_id` INT, IN `p_admin_id` INT)   BEGIN
    DECLARE v_car_id INT;
    DECLARE v_customer_id INT;
    DECLARE v_rent_from DATETIME;
    DECLARE v_rent_to DATETIME;
    DECLARE v_customer_email VARCHAR(255);

    SELECT ra.car_id, ra.customer_id, ra.rent_from, ra.rent_to, c.email
    INTO v_car_id, v_customer_id, v_rent_from, v_rent_to, v_customer_email
    FROM rent_approvals ra
    JOIN customers c ON ra.customer_id = c.id
    WHERE ra.id = p_rent_approval_id;
    
    SELECT email INTO v_customer_email
    FROM customers
    WHERE id = v_customer_id;

    INSERT INTO reservations (car_id, customer_id, reservation_date, start_date, end_date)
    VALUES (v_car_id, v_customer_id, NOW(), v_rent_from, v_rent_to);

    DELETE FROM rent_approvals
    WHERE id = p_rent_approval_id;
    
    SELECT v_customer_email AS customer_email;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `ApproveRequest` (IN `c_customer_id` INT, IN `c_admin_id` INT)   BEGIN
    SELECT *
    FROM customers
    WHERE id = c_customer_id;

    UPDATE customers
    SET isApproved = TRUE
    WHERE id = c_customer_id;

    UPDATE approvals
    SET approved_by = c_admin_id, approved_at = NOW()
    WHERE customer_id = c_customer_id;

END$$

