CREATE DEFINER=`root`@`localhost` PROCEDURE `CreateRentApproval` (IN `p_car_id` INT, IN `p_customer_id` INT, IN `p_rent_from` DATE, IN `p_rent_to` DATE)   BEGIN
    INSERT INTO rent_approvals (car_id, customer_id, rent_from, rent_to, approved_by, approved_at)
