CREATE DEFINER=`root`@`localhost` PROCEDURE `DeleteCar` (IN `c_id` INT)   BEGIN
    DECLARE pic_id INT;

    SELECT car_picture_id INTO pic_id
    FROM cars
    WHERE id = c_id;

    DELETE FROM cars
    WHERE id = c_id;

    DELETE FROM car_pictures
    WHERE id = pic_id;
END$$

