CREATE DEFINER=`root`@`localhost` PROCEDURE `DenyApproveRequest` (IN `c_customer_id` INT)   BEGIN    
	SELECT * FROM customers WHERE customers.id = c_customer_id;

    DELETE FROM approvals
    WHERE approvals.customer_id = c_customer_id;
    
    DELETE FROM customers
    WHERE customers.id = c_customer_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `DenyRentRequest` (IN `p_id` INT)   BEGIN
	DECLARE v_customer_email VARCHAR(255);

	SELECT c.email
    INTO v_customer_email
    FROM rent_approvals ra
    JOIN customers c ON ra.customer_id = c.id
    WHERE ra.id = p_id;

    DELETE FROM rent_approvals WHERE id = p_id;
    
    SELECT v_customer_email AS customer_email;
END$$

