CREATE DEFINER=`root`@`localhost` PROCEDURE `FilterAllCarFuel` ()   SELECT DISTINCT brand, model, cc, available, isDiesel FROM cars$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `FilterCars` (IN `c_category` VARCHAR(16), IN `c_isDiesel` TINYINT(10), IN `c_min_price` INT, IN `c_max_price` INT, IN `c_isManual` TINYINT)   BEGIN
    SELECT *
    FROM cars
    WHERE category = c_category
      AND isDiesel= c_isDiesel
      AND price_per_day BETWEEN c_min_price
      AND isManual = c_isManuel                
      AND c_max_price;
END$$

