CREATE DEFINER=`root`@`localhost` PROCEDURE `GetApprovalById` (IN `p_approval_id` INT)   BEGIN
    SELECT 
        approvals.id AS approval_id,
        customers.id AS customer_id,
        customers.first_name AS customer_first_name,
        customers.last_name AS customer_last_name,
        customers.email AS customer_email,
        driver_license_pictures.picture_front,
        driver_license_pictures.picture_back,
        approvals.picture_set_id
    FROM approvals
    JOIN customers ON approvals.customer_id = customers.id
    JOIN driver_license_pictures ON approvals.picture_set_id = driver_license_pictures.id
    WHERE approvals.id = p_approval_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `GetCarById` (IN `c_id` INT(1))   BEGIN
    SELECT cars.id, brand, model, cc, year, license_plate, category, available, price_per_day, mileage, isDiesel, last_service_date, doors, seats, isManual, car_data.description, car_data.equipments, cars.car_picture_id, car_pictures.thumbnail
    FROM cars
    JOIN car_pictures ON cars.car_picture_id = car_pictures.id
    LEFT JOIN car_data ON cars.id = car_data.car_id
    WHERE cars.id = c_id;
END$$

