CREATE DEFINER=`root`@`localhost` PROCEDURE `GetInvoice` (IN `c_rental_id` INT)   BEGIN
    SELECT 
        r.id AS rental_id,
        r.rental_date,
        r.return_date,
        r.total_price,
        r.deposit_amount,
        r.deposit_status,
        c.first_name,
        c.last_name,
        c.email,
        ca.brand,
        ca.model,
        ca.license_plate
    FROM rentals r
    JOIN customers c ON r.customer_id = c.id
    JOIN cars ca ON r.car_id = ca.id
    WHERE r.id = c_rental_id;
END$$

