CREATE DEFINER=`root`@`localhost` PROCEDURE `GetRentApprovalById` (IN `r_id` INT)   BEGIN
    SELECT 
        rent_approvals.id AS approval_id,
        rent_approvals.customer_id,
        customers.first_name AS customer_first_name,
        customers.last_name AS customer_last_name,
        cars.brand,
        cars.model,
        cars.cc,
        rent_approvals.rent_from,
        rent_approvals.rent_to,
        rent_approvals.approved_by,
        rent_approvals.approved_at
    FROM rent_approvals
    JOIN customers ON rent_approvals.customer_id = customers.id
    LEFT JOIN cars ON rent_approvals.car_id = cars.id
    WHERE rent_approvals.approved_by IS NULL AND rent_approvals.id = r_id;
END$$

