CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateCar` (IN `c_id` INT, IN `c_brand` VARCHAR(20), IN `c_model` VARCHAR(32), IN `c_cc` VARCHAR(10), IN `c_year` INT, IN `c_license_plate` VARCHAR(10), IN `c_category` VARCHAR(16), IN `c_available` TINYINT, IN `c_price_per_day` INT, IN `c_mileage` INT, IN `c_isDiesel` VARCHAR(10), IN `c_last_service_date` DATE, IN `c_car_img_path` VARCHAR(128), IN `c_seats` INT, IN `c_isManual` TINYINT)   BEGIN
