CREATE DEFINER=`root`@`localhost` PROCEDURE `ValidateResetToken` (IN `input_token` VARCHAR(255))   BEGIN
    DECLARE reset_token_id INT;
    DECLARE token_customer_id INT;

    SELECT id INTO reset_token_id
    FROM reset_tokens
    WHERE token = input_token AND expires_at > NOW();
    
    SELECT customer_id INTO token_customer_id
    FROM reset_tokens
    WHERE token = input_token AND expires_at > NOW();

    SELECT reset_token_id, token_customer_id;
END$$

